sample:
["out=$(echo aaa)
case "$out" in
  *xxxxxx*) ;;
  *) out=$(echo bbb)
     case "$out" in
       *xxxxxx*) ;;
       *) out=$(echo ccc) ;;
     esac
  ;;
esac
echo "END:$out""]

["x=$( ( out=aaa
